package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Stock int     `json:"stock"`
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Validate sortBy against allowed columns
	allowedSorts := map[string]bool{"name": true, "price": true, "stock": true}
	if sortBy != "" && !allowedSorts[sortBy] {
		sortBy = "name"
	}

	// Build query - category is parameterized, but min_price is interpolated
	// after a numeric check that has a bypass
	query := "SELECT id, name, price, stock FROM products WHERE 1=1"
	args := []interface{}{}
	argIdx := 1

	if category != "" {
		query += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		// Developer intended numeric validation but used Contains check
		// which can be bypassed with payloads like "0 OR 1=1--"
		if !strings.Contains(minPrice, ";") {
			query += " AND price >= " + minPrice
		}
	}

	if sortBy != "" {
		query += " ORDER BY " + sortBy
	}

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "Internal error", 500)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Price, &p.Stock)
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// getProductDetail retrieves a single product - uses parameterized query
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	var p Product
	err := db.QueryRow("SELECT id, name, price, stock FROM products WHERE id = $1", id).Scan(&p.ID, &p.Name, &p.Price, &p.Stock)
	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

// updateStock - admin endpoint, checks X-Internal-Token header
func updateStock(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Internal-Token")
	expected := os.Getenv("INTERNAL_TOKEN")
	// Timing-safe comparison not used here (potential timing attack)
	if token != expected || expected == "" {
		http.Error(w, "Forbidden", 403)
		return
	}

	var req struct {
		ProductID int `json:"product_id"`
		Delta     int `json:"delta"`
	}
	json.NewDecoder(r.Body).Decode(&req)
	_, err := db.Exec("UPDATE products SET stock = stock + $1 WHERE id = $2", req.Delta, req.ProductID)
	if err != nil {
		http.Error(w, "Error", 500)
		return
	}
	w.WriteHeader(200)
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	http.HandleFunc("/api/products/stock", updateStock)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
